package zombie.core.skinnedmodel.model;
public final class VertexBufferObject{public enum VertexType{VertexArray,BlendWeightArray,BlendIndexArray}public static final class VertexElement{public int byteSize;public VertexElement(int n){byteSize=n;}}public static final class VertexFormat{public final VertexElement[] elements={new VertexElement(12),new VertexElement(16),new VertexElement(16)};public int indexOf(VertexType type){return type.ordinal();}public VertexElement getElement(int n){return elements[n];}}public static final class VertexArray{public final VertexFormat format=new VertexFormat();public final int numVertices;public final float[][][] data;public VertexArray(int n){numVertices=n;data=new float[n][3][4];}public float getElementFloat(int v,int e,int c){return data[v][e][c];}}}
